.switch {
    display: inline-block;
    position: relative;
    padding: 4px;
    background-color: $gray100;
    width: 200px;
    height: 48px;
    border-radius: 50px;
    font-size: $font-sm;
    box-shadow: inset 0 0px 6px $gray200;

    input {
        position: absolute;
        opacity: 0;
    }

    label {
        position: relative;
        z-index: 2;
        float: left;
        width: 96px;
        height: 40px;
        line-height: 40px;
        text-align: center;
        color: $primary-color;
        cursor: pointer;
        transition: color 0s ease 0.2s;
    }

    input:checked + label {
        color: $white;
    }

    input:focus + label {
        outline: none;
    }

    .switch-button {
        clear: both;
        position: absolute;
        top: 4px;
        left: 4px;
        z-index: 1;
        display: inline-block;
        width: 96px;
        height: 40px;
        background: $primary-color;
        border-radius: 50px;
        transition: all 0.3s ease-out;
    }

    input:last-of-type:checked ~ .switch-button {
        left: 100px;
    }
}

.order {
    height: calc(100vh - 232px);
    padding-right: 8px;
    overflow-x: hidden;

    & > li {
        margin-bottom: $w-sm;
    }

    &[data-con="member"] {
        height: calc(100vh - 375px);
    }
}

.order-card {
    width: 100%;
    display: flex;
    align-items: center;
    flex-wrap: nowrap;
    align-items: stretch;
    transition: margin-bottom 0.4s ease;

    &:has(.show) {
        margin-bottom: 0;
    }

    &.merging {
        .order-card-check {
            margin-left: 0;
        }

        .order-card-item {
            width: calc(100% - 32px);
            pointer-events: none;
        }
    }

    &-check {
        width: 32px;
        margin-bottom: 0;
        padding-bottom: 0;
        display: flex;
        align-items: center;
        border-bottom: none;
        margin: 0 0 0 -32px;
        flex-shrink: 0;
        transition: margin-left 0.4s ease;

        .form-check-input {
            pointer-events: none;
            width: 20px;
            height: 20px;
            border: 1px solid $primary-light-color;
        }

        &:has(input:checked) ~ .order-card-item {
            border-color: $primary-pale-color;
        }
    }

    &-item {
        width: 100%;
        display: block;
        padding: $w-sm 22px;
        background: $white;
        color: $primary-color;
        border: 1px solid $gray200;
        border-left: 6px solid $gray600;
        border-radius: $w-xxxs;
        box-shadow: 0 0 6px $gray300;
        transition: all 0.2s ease;
        position: relative;
        flex-shrink: 0;

        &.active {
            flex-shrink: 1;
            border: 1px solid $alert-xlight-color;
            border-left: 6px solid $alert-xlight-color;

            &:after {
                content: " ";
                display: block;
                width: calc(100% + 1px);
                height: 100%;
                border: 1px solid $alert-xlight-color;
                position: absolute;
                border-radius: 0 $w-xxxs $w-xxxs 0;
                left: -1px;
                top: 0;
                pointer-events: none;
            }

            .order-card-tag {
                background: $primary-light-color;
                opacity: 0.6;
            }
        }
    }

    &-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
    }

    &-title {
        font-size: $font-smd;
        font-variation-settings: $font-bold;
    }

    &-tag {
        background: $gray500;
        border-radius: 50px;
        padding: 0 $w-sm;
        height: 27px;
        line-height: 26px;
        color: $white;
        font-size: $font-xs;
    }

    &-info {
        display: flex;
        align-items: center;
        color: $gray900;
        font-size: $font-xs;

        li {
            line-height: 1.2;
            border-right: 1px solid $gray500;
            padding: 0 $w-xxs;

            &:first-child {
                padding-left: 0;
            }

            &:last-child {
                border-right: 0;
            }
        }
    }

    &-price {
        display: flex;
        align-items: center;

        span {
            text-decoration: line-through;
            color: $gray600;
            font-size: $font-xxs;
        }

        p {
            font-size: $font-lg;
            font-variation-settings: $font-heavy;
        }

        div {
            border-radius: 3px;
            font-variation-settings: normal;
        }
    }

    &-body {
        display: flex;
        justify-content: space-between;
        flex: 0 0;
    }

    &-function {
        flex: 0 0;
        color: $white;
        display: flex;
        justify-content: center;
        align-items: center;
        margin-left: $w-xs;

        & > button {
            height: 100%;
            width: 48px;
            padding: 0;
            border-radius: 0;
            font-size: $font-xsm;

            &:first-child {
                border-top-left-radius: $w-xxxs !important;
                border-bottom-left-radius: $w-xxxs !important;
                border-radius: $w-xxxs 0 0 $w-xxxs;

                button {
                    border-top-left-radius: $w-xxxs !important;
                    border-bottom-left-radius: $w-xxxs !important;
                    border-radius: $w-xxxs 0 0 $w-xxxs;
                }
            }

            &:last-child {
                border-radius: 0 $w-xxxs $w-xxxs 0;

                button {
                    border-radius: 0 $w-xxxs $w-xxxs 0;
                }
            }
        }
    }
}

.order-dropdown {
    width: 100%;
    z-index: 100;
    position: relative;
    transition: all 0.1s ease;
    height: 0;

    &.show {
        height: 56px;
    }

    &-item {
        position: relative;
        display: inline-block;
        position: absolute;
        top: 4px;
        display: none;

        &:before {
            content: "";
            display: block;
            width: 16px;
            height: 16px;
            margin: 4px 16px -12px auto;
            transform: rotate(45deg);
            border-radius: 3px;
            z-index: 0;
            transition: all 0.1s ease;
        }

        &[data-con="print"] {
            //補印
            right: 96px;

            &::before {
                background: $alert-light-color;
            }

            ul {
                border-color: $alert-light-color;
            }
        }

        &[data-con="merge"] {
            //合併
            right: 48px;

            &::before {
                background: $primary-pale-color;
            }

            ul {
                border-color: $primary-pale-color;
            }

            li:first-child {
                background: $primary-pale-color;
                color: $white;
                display: flex;
                align-items: center;
                padding: 0 $w-sm;

                span {
                    display: inline-flex;
                    border-radius: 20px;
                    background: $primary-light-color;
                    min-width: 24px;
                    height: 24px;
                    justify-content: center;
                    align-items: center;
                    padding: 0 $w-xxs 2px $w-xxs;
                    margin-left: $w-xxxs;
                    line-height: 0.9;
                }
            }
        }

        &.show {
            &:before {
                top: -4px;
            }
        }

        ul {
            background: $white;
            border-radius: $w-xxxs;
            border: 2px solid;
            position: relative;
            z-index: 10;
            display: flex;
            flex-shrink: 0;
            transition: all 0.1s ease;

            li:last-child {
                a {
                    &:after {
                        display: none;
                    }
                }
            }

            a {
                font-family: "Noto Sans TC", "Microsoft JhengHei", "sans-serif";
                font-size: $font-sm;
                color: $gray800;
                padding: $w-xxs $w-xs;
                text-align: center;
                display: block;
                position: relative;

                &:after {
                    content: "";
                    display: block;
                    width: 1px;
                    height: 18px;
                    right: 0;
                    top: 12px;
                    position: absolute;
                    background: $gray400;
                }

                &:hover {
                    color: $gray900;
                }
            }
        }
    }
}

//優惠券
.coupon-list {
    &-item {
        display: flex;
        width: 100%;
        border-radius: 8px;
        margin-bottom: 12px;
        background: $white;
        border: 2px solid $gray100;
        position: relative;

        &:active {
            background: $white !important;
            border: 2px solid $gray100 !important;
        }

        &:last-child {
            margin-bottom: 0;
        }

        &.active,
        &.active:active {
            border: 2px solid $danger-color !important;
            background: $white !important;

            &::after {
                content: "";
                display: inline-block;
                flex-shrink: 0;
                width: 30px;
                height: 30px;
                background: url("../images/ic-picked.svg") no-repeat;
                margin-top: 6px;
            }

            .coupon-list-title {
                color: $danger-color;

                img {
                    filter: invert(69%) sepia(7%) saturate(6313%) hue-rotate(312deg) brightness(106%) contrast(93%);
                }
            }
        }

        &[data-status] {
            //未符合
            position: relative;
            background: $gray100;
            border: none;
            pointer-events: none;

            &:after {
                content: attr(data-status);
                display: block;
                background: $gray600;
                color: $white;
                border-radius: 30px;
                padding: 4px 12px;
                margin-left: auto;
                position: absolute;
                line-height: 1;
                right: 16px;
                top: 8px;
                font-size: $font-xxs;
            }

            .coupon-list-title {
                color: $gray600;

                img {
                    filter: none;
                }
            }
        }

        &[data-member="none"] {
            .coupon-list-title {
                img {
                    display: none;
                }
            }
        }
    }

    &-con {
        width: 100%;
        text-align: left;
        font-weight: 500;
    }

    &-title {
        display: flex;
        align-items: center;
        margin-bottom: 4px;
        padding-right: 72px;
        color: $primary-color;

        img {
            margin-right: 4px;
            filter: invert(50%) sepia(10%) saturate(4176%) hue-rotate(162deg) brightness(90%) contrast(91%);
        }
    }

    &-txt {
        margin-bottom: -2px;
        font-size: $font-xs;

        & ~ span {
            font-size: $font-xxs;
            color: $gray700;
        }
    }

    &-btn {
        width: 60px;
        height: 40px;
        border-radius: 5px;
        color: $white;
        background: $danger-color;
        display: flex;
        justify-content: center;
        align-items: center;
        position: absolute;
        right: 12px;
        top: 12px;
        padding: 0;
        font-size: $font-xs;
        display: none;
    }
}

.checkout-coupon-list {
    .coupon-list-item {
        &.active {
            .coupon-list-btn {
                display: flex;
            }
        }

        &.active::after {
            display: none;
        }
    }
}

.top-nav[data-con="filter"] {
    .top-nav-item {
        display: inline-flex;
        align-items: center;
        margin-right: 8px;
    }

    .top-nav-btn {
        height: 48px;
        padding: 0 $w-sm 0 38px;
        display: flex;
        border: 1px solid $gray300;
        font-variation-settings: $font-bold;
        position: relative;

        &-icon {
            position: absolute;
            border-radius: 50%;
            background: $white;
            width: 16px;
            height: 16px;
            border: 1px solid $primary-color;
            left: 16px;
            top: 16px;
            transition: all 0.1s ease;
        }

        &.active {
            background: $primary-color;
            color: $white;
            font-variation-settings: $font-light;

            .top-nav-btn-icon {
                border: 4px solid $white;
                background: $primary-color;
            }
        }
    }
}

[data-con="carrier"] {
    position: relative;

    &::before {
        content: "/";
        display: block;
        position: absolute;
        left: 101px;
        top: 5px;
        width: 15px;
        height: 30px;
        color: $gray800;
        z-index: 10;
        font-size: $font-md;
        font-variation-settings: $font-heavy;
    }

    input {
        padding-left: 25px;
    }
}

.offcanvas-body {
    .setting-wrapper {
        padding: 0 32px 24px 32px;
    }
}

.setting-wrapper {
    height: calc(100vh - 99px);
    padding-right: 8px;
    overflow-x: hidden;

    .form-control {
        border: 1px solid $primary-color;

        &[disabled] {
            border: 1px solid $gray500;
        }

        &[readonly] {
            border: 1px solid $gray300;
        }

        &[type="file"] {
            border-radius: 0.375rem !important;
        }

        & ~ button {
            border-radius: 0 0.375rem 0.375rem 0 !important;
        }
    }

    .form-select {
        border: 1px solid $primary-color;
        background-image: url("../images/ic-dropdown.svg");
    }

    .input-group[type="file"] {
        position: relative;

        button {
            position: absolute;
            left: 0;
            top: 0;
            height: 100%;
            width: 91px;
            border-radius: 0.375rem 0 0 0.375rem !important;
            padding-left: 0;
            padding-right: 0;
            z-index: 100;
            pointer-events: none;
        }
    }

    .form-check-input[disabled] {
        background-color: $gray200;
    }

    .form-switch {
        margin-bottom: 10px;
    }

    .form-check-input[role="switch"] {
        height: 30px;
        width: 55px;
        margin-top: -2px;
        margin-right: 8px;
        background-color: $gray300;
        background-image: url("../images/ic-switch.svg");
        background-position: -3px -4px;
        background-size: 38px;
        border: none;

        &:checked {
            background-color: $primary-color !important;
            background-position: 20px -4px;
        }
    }
}

.form-check-input:checked {
    background-color: $primary-color;
    border-color: $primary-color;
}

#date-inline-picker {
    thead {
        th[title="Select Month"] {
            height: 54px;
            vertical-align: middle;
        }

        tr:last-child {
            background: $primary-color;

            th {
                border-radius: 0;
                color: $white;
                padding-top: 6px;
                padding-bottom: 8px;
                font-weight: $font-light;

                &:first-child {
                    border-radius: 5px 0 0 5px;
                }

                &:last-child {
                    border-radius: 0 5px 5px 0;
                }
            }
        }
    }

    tbody {
        tr {
            border-bottom: 1px solid $gray300;

            &:last-child {
                border-bottom: none;
            }

            p {
                position: relative;
                z-index: 1;
            }
        }
    }
}

.input-group-text {
    box-shadow: none !important;
    border: none !important;

    &:active {
        box-shadow: none !important;
        border: none !important;
    }
}

[data-func="setting"] {
    .setting-wrapper {
        height: calc(100vh - 308px);
    }
    .form-switch {
        flex-direction: column;
        align-items: center;
        padding-left: 12px;
        padding-bottom: 0;
        margin-bottom: 0;
        transition: all 0.2s ease;
    }

    .form-check-input[role="switch"] {
        height: 30px;
        width: 55px;
        margin-top: 0;
        background-color: $gray300;
        background-image: url("../images/ic-switch.svg");
        background-position: -3px -4px;
        background-size: 38px;
        border: none;
        margin-left: 0;
        margin-right: 0;
        margin-bottom: 4px;
        &:checked {
            background-color: $primary-pale-color !important;
            background-position: 20px -4px;
        }
    }
    .top-nav{
        .form-check-label {
            display: none;
        }
    }

    .top-nav-link {
        color: $gray800;
        padding-right: 60px;
        padding-left: 20px;
        font-weight: 500;
        &::before {
            background: $white;
            border: 1px solid $white;
        }
        &.active {
            color: $white;
            border: none !important;
            &::before {
                background: $gray700;
                border: 1px solid $gray700;
            }
            &::after {
                background: $gray700;
            }
            &~.form-switch{
                .form-check-input[role="switch"]:checked{
                    background-color: $primary-xlight-color !important;
                }
            }
        }
    }

    .top-nav-item {
        margin-right: 0;
        .form-switch {
            z-index: 10;
            transform: scale(.6);
            margin-left: -70px;
            margin-top: 7px;
        }
    }

    .top-nav-item:has([role="switch"]:checked) {
        .top-nav-link {
            color: $primary-color;
            &::before {
                background: $white;
                border: 1px solid $gray200;
            }
            &.active {
                color: $white;
            }
            &.active::before {
                background: $primary-color !important;
                border: 1px solid $primary-color;
            }
            &.active::after {
                background: $primary-color !important;
            }
        }
    }
}

.menu-edit-list {
    display: flex;
    border-radius: $w-xxs;
    background: $gray100;
    padding: 16px;
    .menu-edit-pic {
        width: 58px;
        height: 58px;
        margin-right: 16px;
        border-radius: 5px;
        flex-shrink: 0;
        overflow: hidden;
        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }
    .form-check-input[role="switch"] {
        margin-bottom: 0;
        margin-top: 16px;
    }
    .form-check[data-con="checkbox"]{
        padding-bottom: 0;
        margin-bottom: 0;
        margin-top: -4px;
        min-height: 32px;
        display: flex;
        align-items: center;
        justify-content: center;
        .form-check-input{
            margin-right: 6px;
        }
        .form-check-label {
            flex-shrink: 0;
            margin-top: 3px;
        }
        &:has(.form-check-input:checked){
            &~.number-form{
                margin-top: 0;
                opacity: 1;
                pointer-events: initial;
            }
        }
    }
    .number-form{
        opacity: 0;
        margin-top: -30px;
        transition: all 0.2s ease;
        pointer-events: none;
    }
    .form-switch {
        width: 67px;
        flex-shrink: 0;
        margin-right: 0;
        .form-check-label{
            display: none;
        }
    }
    p {
        margin-bottom: 6px;
    }
}
/*toast通知功能*/
#toast-container {
    position: fixed;
    bottom: 20px;
    right: 20px;
    z-index: 9999;
    display: flex;
    flex-direction: column-reverse; // 新的往上堆
    gap: 10px;
}

.custom-toast {
    display: none; /* 預設隱藏，由 JQ 的 fadeIn 控制 */
    pointer-events: auto;
    width: 328px;
    padding: 12px 40px 12px 16px;
    border-radius: 8px;
    color: $white;
    font-size: $font-xs;
    position: relative;
    overflow: hidden; /* 確保收縮時內容不溢出 */
    transition: all 0.2s ease;
    &.active {
        background: rgba($color: $primary-stable-color, $alpha: .9);
    }
    &.inactive {
        background: rgba($color: $gray600, $alpha: .9); 
    }
    & .close {
        position: absolute;
        right: 10px;
        top: 8px;
        cursor: pointer;
        font-weight: bold;
        z-index: 20;
    }
}